typedef struct Reducer {                 /* one composed stage */
    void  (*init)(void *st);
    bool  (*step)(void *st, const void *in, void *acc);   /* false = stop */
    void *state;                         /* per-application stage state */
    const struct Reducer *next;          /* downstream stage */
} Reducer;
static bool map_step(void *st, const void *in, void *acc) {
    MapCtx *m = st;
    Out o = m->f(m->ctx, in);            /* element in, element out */
    return m->next->step(m->next->state, &o, acc);
}
